        )

    user_id = SESSIONS_DB[token]
    if user_id != "moderator":
        return JSONResponse(
            status_code=status.HTTP_401_UNAUTHORIZED,
            content={"error": "Access denied: Moderator permissions required."},
        )

    return REVIEWS_DB


